// Contact Form Handler with Security
(function() {
  'use strict';
  
  const form = document.getElementById('contactForm');
  const status = document.querySelector('.form-status');
  
  if (!form || !status) return;
  
  // Form submission handler
  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    
    const submitBtn = form.querySelector('button[type="submit"]');
    const originalText = submitBtn.textContent;
    
    // Disable submit button
    submitBtn.disabled = true;
    submitBtn.textContent = 'Изпраща се...';
    status.textContent = '';
    status.className = 'form-status';
    
    try {
      const formData = new FormData(form);
      
      // Client-side validation
      const name = formData.get('name').trim();
      const phone = formData.get('phone').trim();
      const email = formData.get('email').trim();
      
      if (name.length < 2) {
        throw new Error('Моля въведете валидно име');
      }
      
      if (!/^[0-9]{10,15}$/.test(phone.replace(/\s/g, ''))) {
        throw new Error('Моля въведете валиден телефонен номер');
      }
      
      if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        throw new Error('Моля въведете валиден email адрес');
      }
      
      // Submit to serverless function
      const response = await fetch('/api/contact', {
        method: 'POST',
        body: formData,
        headers: {
          'Accept': 'application/json'
        }
      });
      
      const result = await response.json();
      
      if (response.ok && result.success) {
        status.textContent = '✓ Благодарим! Ще се свържем с вас в най-кратък срок.';
        status.className = 'form-status success show';
        form.reset();
        
        // Reset Turnstile widget
        if (window.turnstile) {
          const widget = form.querySelector('.cf-turnstile');
          if (widget) {
            turnstile.reset(widget);
          }
        }
      } else {
        throw new Error(result.error || 'Грешка при изпращане');
      }
    } catch (error) {
      console.error('Form submission error:', error);
      status.textContent = `✗ ${error.message || 'Възникна грешка. Моля обадете се на 0888 123 456'}`;
      status.className = 'form-status error show';
    } finally {
      submitBtn.disabled = false;
      submitBtn.textContent = originalText;
    }
  });
  
  // Input sanitization on blur
  const sanitizeInput = (input) => {
    input.addEventListener('blur', function() {
      this.value = this.value.replace(/[<>]/g, '').trim();
    });
  };
  
  form.querySelectorAll('input, textarea').forEach(sanitizeInput);
  
  // Smooth scroll for anchor links
  document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function(e) {
      e.preventDefault();
      const targetId = this.getAttribute('href');
      if (targetId === '#') return;
      
      const target = document.querySelector(targetId);
      if (target) {
        const offset = 80; // Account for fixed header if any
        const targetPosition = target.getBoundingClientRect().top + window.pageYOffset - offset;
        
        window.scrollTo({
          top: targetPosition,
          behavior: 'smooth'
        });
      }
    });
  });
  
})();
